						{ "latex": "x = x_0 + v_0 t + \\frac{1}{2}at^2", "note": "מקום-זמן" },
						{ "latex": "x - x_0 = \\frac{v + v_0}{2}t", "note": "מקום-זמן" },
						{ "latex": "v^2 = v_0^2 + 2a(x - x_0)", "note": "קשר ללא זמן" },
						{ "latex": "v_{B/A} = -v_{A/B}", "note": "מהירות יחסית" }
