						{ "latex": "W_T = \\Delta E_k", "note": "משפט עבודה-אנרגיה" },
						{ "latex": "W_{\\text{םירמשמ אל}} = \\Delta E", "note": "שינוי אנרגיה מכנית כוללת" },
