						{ "latex": "m_Av_A + m_Bv_B = m_Au_A + m_Bu_B", "note": "שימור תנע" },
						{ "latex": "v_B - v_A = -(u_B - u_A)", "note": "התנגשות אלסטית חד-ממדית" }
					]
				}
			]
		},
		{
			"topic": "נוסחאות מכניקה",
			"sourcePage": 3,
			"subtopics": [
